const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
  await page.goto('http://127.0.0.1:8092/index.html#/market-monitor', { waitUntil: 'networkidle' });
  await page.waitForTimeout(2500);
  await page.screenshot({ path: 'tests/e2e/screenshots/kpi-verify.png', fullPage: false });
  // crop the top KPI section
  const el = await page.$('section');
  if (el) { await el.screenshot({ path: 'tests/e2e/screenshots/kpi-section.png' }).catch(()=>{}); }
  await browser.close();
})();

